import { Component, OnInit } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { NetworkService, ConnectionStatus } from 'src/app/services/network-service';

@Component({
  selector: 'app-vasipuiyakamprofile',
  templateUrl: './vasipuiyakamprofile.page.html',
  styleUrls: ['./vasipuiyakamprofile.page.scss'],
})
export class VasipuiyakamprofilePage implements OnInit {
  ambastorListData: any[];
  form: FormGroup;
  checkBox: boolean = true;
  emis_username: any;
  userStatus: any;
  dataList: any[] = [];
  allBankDetails: any;
  dataList1: any;
  searchData: any[];
  filterActive: boolean;
  searchTerm: any;
  isInputDisabled: boolean;
  isInputDisabled1: boolean = false;

  constructor(private router: Router, private userService: UserService,
    private usersessionService: UserSessionService, private sqliteDB: SqlitedatabaseService,
    private NetworkService: NetworkService) {
    this.emis_username = this.usersessionService.emis_username();
  }

  ngOnInit() {
    this.initialValidator()
  }

  ionViewDidEnter() {
    this.filterActive = false;
    this.isInputDisabled = true;

    // this.getServerData()
    this.localData()
    this.localDataForBank()   
  }

  localDataForBank(){
    let query = 'SELECT * FROM viBankDetails';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.dataList1 = []
        for (var i = 0; i < data.rows.length; i++) {
          this.dataList1.push(data.rows.item(i));
        }
        this.allBankDetails = this.dataList1
        console.log('in Local Bank');
      } else {
        this.getServerDataForBank()
      }
    })
  }

  getServerDataForBank(){
    fetch('https://d1wpyxz35bzzz4.cloudfront.net/bank_details_json.json').then(res => res.json()).then(manage => {
      console.log("in Server Bank");
      this.allBankDetails = manage.bank_details;
      this.insertLocalDataForBank(this.allBankDetails);
    })
  }

  getServerData() {
    this.ambastorListData = []
    // this.userService.viProfileDetail(this.emis_username).subscribe((response) => {
    fetch('https://d1wpyxz35bzzz4.cloudfront.net/vi_user_bank_detail_json.json').then(res => res.json()).then(manage => {
      if (manage) {
        this.ambastorListData = manage.filter(item=> item.UserId == this.emis_username) 
        this.insertLocalData(this.ambastorListData);
        // this.ambastorListData = response.result
        console.log('in server');
        this.userStatus = this.ambastorListData[0].Status
        this.form.patchValue(this.ambastorListData[0])
        this.userStatus == 0 ? this.form.enable() : this.form.disable();
        // this.form.controls['Name'].disable();
        // this.form.controls['Dob'].disable();
        // this.form.controls['Phone'].disable();
        // this.form.controls['Branch'].disable();
        // this.form.controls['BankName'].disable();
      }
    })
  }

  insertLocalData(elementData) {
    let insertRows = [];
    insertRows.push(([
      "INSERT INTO vasipuIyakam VALUES (?,?,?,?,?,?,?,?,?,?,?)",
      [null, elementData[0].Status, elementData[0].Name, elementData[0].Dob, elementData[0].Phone, elementData[0].AadharNo,
        elementData[0].AccNo, elementData[0].IfscCode, elementData[0].Branch, elementData[0].BankName, elementData[0].UserId]
    ]));


    this.sqliteDB.bulkInsert(insertRows).then((result) => {
      console.info("LocalData Stored Locally");
    })
  }

  insertLocalDataForBank(elementData){
    let insertBank = [];
    insertBank.push(([
      "INSERT INTO viBankDetails VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
      [null, elementData[0].bank, elementData[0].bank_dist_id, elementData[0].bank_id, elementData[0].bank_name, elementData[0].branch,
        elementData[0].branch_add, elementData[0].city, elementData[0].contact_no, elementData[0].district_name, elementData[0].ifsc_code, elementData[0].micr_code]
    ]));

    this.sqliteDB.bulkInsert(insertBank).then((result) => {
      console.info("LocalData Stored Locally");
    })
  }

  localData() {
    let query = 'SELECT * FROM vasipuIyakam';

    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        this.dataList = []
        for (var i = 0; i < data.rows.length; i++) {
          this.dataList.push(data.rows.item(i));
        }
        this.ambastorListData = []
        this.ambastorListData = this.dataList
        console.log('in local',this.ambastorListData);
        this.userStatus = this.ambastorListData[0].Status
        this.form.patchValue(this.ambastorListData[0])
        this.userStatus == 0 ? this.form.enable() : this.form.disable();
        // this.form.controls['Name'].disable();
        // this.form.controls['Dob'].disable();
        // this.form.controls['Phone'].disable();
        // this.form.controls['Branch'].disable();
        // this.form.controls['BankName'].disable();
        console.log(this.form);
      } else {
        this.getServerData()
      }
    })
  }

  initialValidator() {
    this.form = new FormGroup({
      Name: new FormControl('', Validators.required),
      Dob: new FormControl('', Validators.required),
      Phone: new FormControl('', Validators.required),
      AadharNo: new FormControl('', [Validators.required, Validators.pattern('^[2-9]{1}[0-9]{3}[0-9]{4}[0-9]{4}$')]),
      AccNo: new FormControl('', Validators.required),
      IfscCode: new FormControl('', Validators.required),
      Branch: new FormControl('', Validators.required),
      BankName: new FormControl('', Validators.required),
    })
  }

  navigateBack() {
    this.router.navigate(['/tabs/vasipu-iyakam']);
  }

  onEdit() {
    let phone = this.form.controls['Phone'].value.toString()
    if (phone.length != 10) {
      return this.form.controls['Phone'].setErrors({ 'PhoneNO': true })
    }
    if (this.form.valid) {
      this.form.value.Status = 1;
      this.form.value.UserId = this.emis_username;
      let data = { "records": {
      Name : this.form.value.Name,
      Phone : this.form.value.Phone,
      AadharNo: this.form.value.AadharNo,
      AccNo: this.form.value.AccNo,
      Dob : this.form.value.Dob,
      IfscCode: this.form.value.IfscCode,
      Branch: this.form.value.Branch,
      BankName: this.form.value.BankName,
      UserId: this.emis_username,
      Status: 1
        }
      }
      console.log(data,"data",this.form);
      this.userStatus = 1
      // this.userStatus == 0 ? this.form.enable() : this.form.disable();
      this.userService.viProfileEdit(data).subscribe((response) => {  
      this.updateprofileData()
      // this.router.navigate(['/tabs/vasipu-iyakam']);
      })
    } else {
      console.log("no insert");
    }
  }

  autoSync(){
    debugger
    if (this.NetworkService.getCurrentNetworkStatus() == 0) {
       console.log("online")
       this.onEdit();
    }else{
      let phone = this.form.controls['Phone'].value.toString()
    if (phone.length != 10) {
      return this.form.controls['Phone'].setErrors({ 'PhoneNO': true })
    }
      this.userStatus = 0
      // this.userStatus == 0 ? this.form.enable() : this.form.disable();
       console.log("offline")
       this.updateprofileData();
    }
   
  }

  updateprofileData() {
    let query = 'UPDATE vasipuIyakam SET Status="' + this.userStatus + '", AadharNo="' + this.form.value.AadharNo
      + '", Name="' + this.form.value.Name +'",Dob="' + this.form.value.Dob +'", Phone="' + this.form.value.Phone +'", AccNo="' + this.form.value.AccNo + '", IfscCode="' + this.form.value.IfscCode + '", Branch="' + this.form.value.Branch
      + '", BankName="' + this.form.value.BankName + '" WHERE UserId = ' + this.emis_username;

    return this.sqliteDB.update(query).then(res => {
      this.router.navigate(['/tabs/vasipu-iyakam']);
      console.log("Updated In server");
    });
  }

  acceptNotes(event) {
    this.checkBox = event.target.checked;
  }

  getFilterItems(event) {
    debugger
    this.searchData = [];
    this.searchTerm = event.trim();
    if(this.searchTerm.length > 3){
      if (this.searchTerm) {
        this.searchData = this.allBankDetails.filter(item => item.ifsc_code.toLowerCase().includes(this.searchTerm.toLowerCase()));
        this.filterActive = true
      } 
      else {
        this.searchData = this.allBankDetails;
        this.filterActive = true
      }
    }
  }

  patchItems(event){
    this.searchData = [];
    this.filterActive = false;
    this.searchTerm = event.trim();
    if (this.searchTerm) {
      this.searchData = this.allBankDetails.filter(item => item.ifsc_code.toLowerCase().includes(this.searchTerm.toLowerCase()));
    }

    this.form.controls['IfscCode'].setValue(this.searchData[0].ifsc_code)
    this.form.controls['IfscCode'].updateValueAndValidity;

    if(this.searchData[0].ifsc_code == this.form.controls['IfscCode'].value){
      this.form.controls['Branch'].setValue(null)
      this.form.controls['Branch'].setValue(this.searchData[0].branch)
      this.form.controls['Branch'].updateValueAndValidity;
      this.form.controls['BankName'].setValue(null)
      this.form.controls['BankName'].setValue(this.searchData[0].bank_name)
      this.form.controls['BankName'].updateValueAndValidity;
    }
  }
  
}
